\set ON_ERROR_STOP on
begin;
set local search_path = public, extensions;
select no_plan();
select has_table('public','web_push_events','Dauerhafte Ereignisse');
select has_table('public','web_push_deliveries','Dauerhafte Auftraege');
insert into auth.users(id,email) values('a7000000-0000-4000-8000-000000000001','push-delivery@example.test');
insert into auth.sessions(id,user_id,created_at,updated_at) values('a7100000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001',now(),now());
insert into public.workspaces(id,name) values('a7200000-0000-4000-8000-000000000001','Delivery');
insert into public.workspace_members(workspace_id,user_id,role) values('a7200000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','member');
insert into public.web_push_generations(id,user_id,token_hash) values('a7300000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001',repeat('a',64));
insert into public.web_push_devices(id,user_id,session_id,installation_id,endpoint_fingerprint,endpoint,p256dh,auth,vapid_key_id) values('a7300000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001','a7400000-0000-4000-8000-000000000001','fixture','https://fcm.googleapis.com/test',repeat('x',87),repeat('x',22),'v1');
select ok(public.web_push_can_deliver('a7000000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001','test',null,'a7100000-0000-4000-8000-000000000001'),'Eigentest mit aktueller Sitzung');
select ok(public.web_push_can_deliver('a7000000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001','order',null,'a7100000-0000-4000-8000-000000000001'),'Shopereignisse verlangen aktuellen Workspacezugriff');
create temporary table event_fixture as select public.web_push_enqueue_test('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001') as id;
select is((select count(*) from public.web_push_deliveries),1::bigint,'Test legt echte Outbox an');
select is(public.web_push_enqueue_event('duplicate','a7200000-0000-4000-8000-000000000001','test',null,'{"kind":"settings"}','a7300000-0000-4000-8000-000000000001'),public.web_push_enqueue_event('duplicate','a7200000-0000-4000-8000-000000000001','test',null,'{"kind":"settings"}','a7300000-0000-4000-8000-000000000001'),'Quelle idempotent');
select public.web_push_enqueue_event('cleanup-test','a7200000-0000-4000-8000-000000000001','test',null,'{"kind":"settings"}','a7300000-0000-4000-8000-000000000001');
update public.web_push_events set expires_at=now()-interval '1 second' where source_key='cleanup-test';
select public.web_push_cleanup();
select is((select d.status from public.web_push_deliveries d join public.web_push_events e on e.id=d.event_id where e.source_key='cleanup-test'),'expired','Bereinigung beendet abgelaufene Auftraege auch ohne Claims');
select is((select count(*) from public.web_push_claim('v1',false,'{}','{}')),0::bigint,'Pilot ohne Freigabe sendet nicht');
create temporary table claim_a as select * from public.web_push_claim('v1',false,'{}',array['a7300000-0000-4000-8000-000000000001']::uuid[]);
select is((select count(*) from claim_a),2::bigint,'Pilotgeraet claimt Batch');
select is((select count(*) from public.web_push_claim('v1',true,'{}','{}')),0::bigint,'Zweiter Worker bekommt keine aktive Lease');
update public.web_push_deliveries set lease_until=now()-interval '1 second';
create temporary table claim_b as select * from public.web_push_claim('v1',true,'{}','{}');
select is((select attempts from public.web_push_deliveries where id=(select id from claim_b limit 1)),2,'Crash nach Lease zaehlt Versuch');
select ok(not public.web_push_finish((select id from claim_a limit 1),(select binding_generation from claim_a limit 1),(select claim_token from claim_a limit 1),'accepted',null),'Verspaetetes A ueberschreibt B nicht');
select ok(public.web_push_authorize((select id from claim_b limit 1),(select binding_generation from claim_b limit 1),(select claim_token from claim_b limit 1)) is not null,'B hat aktuellen Sendvertrag');
select ok(public.web_push_finish((select id from claim_b limit 1),(select binding_generation from claim_b limit 1),(select claim_token from claim_b limit 1),'retry',120000),'Retry mit Anbieterwartezeit');
select ok((select next_attempt_at>=now()+interval '119 seconds' from public.web_push_deliveries where status='retry'),'Retry-After angewandt');
select ok(public.web_push_finish((select id from claim_b offset 1 limit 1),(select binding_generation from claim_b offset 1 limit 1),(select claim_token from claim_b offset 1 limit 1),'configuration_error',null),'VAPID-Fehler terminal');
select ok((select active from public.web_push_devices limit 1),'Konfigurationsfehler loescht kein Geraet');
update public.web_push_deliveries set next_attempt_at=now()-interval '1 second' where status='retry';
create temporary table claim_c as select * from public.web_push_claim('v1',true,'{}','{}');
delete from public.workspace_members where user_id='a7000000-0000-4000-8000-000000000001';
select is(public.web_push_authorize((select id from claim_c limit 1),(select binding_generation from claim_c limit 1),(select claim_token from claim_c limit 1)),null::jsonb,'Rechteentzug vor Send verweigert');
insert into public.workspace_members(workspace_id,user_id,role) values('a7200000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','member');
select public.web_push_enqueue_test('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001');
create temporary table crash_a as select * from public.web_push_claim('v1',true,'{}','{}');
create temporary table crash_payload as select public.web_push_authorize((select id from crash_a limit 1),(select binding_generation from crash_a limit 1),(select claim_token from crash_a limit 1))->'payload' as payload;
-- Crash nach Anbieterannahme vor SQLquittung: neue Lease darf dieselbe Tagidentitaet erneut senden.
update public.web_push_deliveries set lease_until=now()-interval '1 second' where status='claimed';
create temporary table crash_b as select * from public.web_push_claim('v1',true,'{}','{}');
select is(public.web_push_authorize((select id from crash_b limit 1),(select binding_generation from crash_b limit 1),(select claim_token from crash_b limit 1))->'payload',(select payload from crash_payload),'Crash nach Anbieterannahme behaelt Payload und Tag');
select ok(public.web_push_finish((select id from crash_b limit 1),(select binding_generation from crash_b limit 1),(select claim_token from crash_b limit 1),'accepted',null),'Neue Lease kann bestaetigen');
select ok(not public.web_push_finish((select id from crash_a limit 1),(select binding_generation from crash_a limit 1),(select claim_token from crash_a limit 1),'retry',null),'Verspaeteter Retry ueberschreibt Annahme nicht');
select is((select count(*) from public.web_push_claim('v1',true,'{}','{}')),0::bigint,'Angenommene Auftraege werden nicht wieder geclaimt');
select public.web_push_enqueue_test('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001');
do $$declare claimed record; attempt integer; begin
 for attempt in 1..5 loop
  select * into claimed from public.web_push_claim('v1',true,'{}','{}') limit 1;
  perform public.web_push_finish(claimed.id,claimed.binding_generation,claimed.claim_token,'retry',null);
  update public.web_push_deliveries set next_attempt_at=now()-interval '1 second' where status='retry';
 end loop;
end; $$;
select is((select count(*) from public.web_push_deliveries where attempts=5 and status='expired'),1::bigint,'Maximal fuenf Versuche inklusive Erstversuch');
select public.web_push_enqueue_test('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001');
create temporary table long_retry as select * from public.web_push_claim('v1',true,'{}','{}');
select ok(public.web_push_finish((select id from long_retry limit 1),(select binding_generation from long_retry limit 1),(select claim_token from long_retry limit 1),'retry',86400000),'Langer Retry abgeschlossen');
select is((select status from public.web_push_deliveries where id=(select id from long_retry limit 1)),'expired','Retry nach Ereignisablauf wird verworfen');
select public.web_push_enqueue_test('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001');
update public.web_push_events set expires_at=now()-interval '1 second' where id in(select event_id from public.web_push_deliveries where status='waiting');
select is((select count(*) from public.web_push_claim('v1',true,'{}','{}')),0::bigint,'24h Ablauf sendet nichts mehr');
select public.web_push_settings('a7000000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001','{"action":"test","deviceId":"a7300000-0000-4000-8000-000000000001","workspaceId":"a7200000-0000-4000-8000-000000000001"}');
select public.web_push_settings('a7000000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001','{"action":"test","deviceId":"a7300000-0000-4000-8000-000000000001","workspaceId":"a7200000-0000-4000-8000-000000000001"}');
select public.web_push_settings('a7000000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001','{"action":"test","deviceId":"a7300000-0000-4000-8000-000000000001","workspaceId":"a7200000-0000-4000-8000-000000000001"}');
select throws_ok($$select public.web_push_settings('a7000000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001','{"action":"test","deviceId":"a7300000-0000-4000-8000-000000000001","workspaceId":"a7200000-0000-4000-8000-000000000001"}')$$,'P0001','Push test rate limit','Eigentest maximal drei pro Minute');
create temporary table expired_endpoint as select * from public.web_push_claim('v1',true,'{}','{}');
select ok(public.web_push_finish((select id from expired_endpoint limit 1),(select binding_generation from expired_endpoint limit 1),(select claim_token from expired_endpoint limit 1),'expired',null),'404/410 konkret abgeschlossen');
select ok(not (select active from public.web_push_devices limit 1),'404/410 deaktiviert genau Bindung');
update public.web_push_generations set revoked_at=now()-interval '31 days';
update public.web_push_deliveries set status='expired',finished_at=now()-interval '8 days';
update public.web_push_events set created_at=now()-interval '31 days';
select public.web_push_cleanup();
select is((select count(*) from public.web_push_deliveries),0::bigint,'Versandhistorie sieben Tage');
select is((select count(*) from public.web_push_events),0::bigint,'Ereignisse dreissig Tage');
select is((select count(*) from public.web_push_devices),0::bigint,'Deaktivierte Bindung dreissig Tage');
select is((select count(*) from public.web_push_generations),1::bigint,'Generationstombstone bleibt nach Bereinigung');
select ok(not has_table_privilege('authenticated','public.web_push_events','insert'),'Clients erzeugen keine Ereignisse');
select ok(not has_table_privilege('anon','public.web_push_deliveries','select'),'Keine Subscription Secrets in Outbox');
select ok(not has_function_privilege('authenticated','public.web_push_claim(text,boolean,uuid[],uuid[])','execute'),'Claim service-only');
select ok(not has_function_privilege('anon','public.web_push_enqueue_test(uuid,uuid)','execute'),'Enqueue service-only');
select * from finish();
rollback;
